// Verbatim port of api_settings.html inline script wrapped for the SPA — regenerated by
// scripts/wrap_p5_js.py; edit the generator, not this file.
import { exposeGlobals, unexposeGlobals } from '../../../../lib/legacy.js';

export function init(ctx, d, G) {
  let _dead = false;
  void d; void G;
  function syncAll() {
    const jobs = G.SYNC_JOBS;

    const totalJobs = jobs.length;
    let idx = 0;

    const toast = document.getElementById('sync-toast');
    const title = document.getElementById('sync-toast-title');
    const bar   = document.getElementById('sync-toast-bar');
    const pct   = document.getElementById('sync-toast-pct');
    const lbl   = document.getElementById('sync-toast-label');
    const btn   = document.getElementById('sync-all-btn');

    if (btn) { btn.disabled = true; btn.textContent = '↻ Syncing…'; }
    toast.style.display = '';
    bar.style.background = 'var(--ttrpg-accent)';

    function runNext() {
      if (idx >= totalJobs) {
        bar.style.width = '100%';
        pct.textContent = '100%';
        bar.style.background = '#28a745';
        title.textContent = '✓ All Libraries Synced';
        lbl.textContent = 'All ' + totalJobs + ' libraries updated.';
        if (btn) { btn.disabled = false; btn.textContent = '✓ Done'; }
        ctx.after(2500, () => { toast.style.display = 'none'; ctx.reload(); });
        return;
      }

      const job = jobs[idx++];
      const overallPct = Math.round((idx - 1) / totalJobs * 100);
      title.textContent = '↻ Syncing ' + idx + '/' + totalJobs + ': ' + job.label + '…';
      bar.style.width = overallPct + '%';
      pct.textContent = overallPct + '%';
      lbl.textContent = 'Starting…';

      fetch(job.syncUrl, { method: 'POST', headers: { 'X-Requested-With': 'XMLHttpRequest' } })
        .then(r => r.json())
        .then(data => {
          if (data.error) {
            lbl.textContent = '✗ ' + data.error + ' — skipping';
            ctx.after(1500, runNext);
            return;
          }
          pollJob(job);
        })
        .catch(() => { lbl.textContent = '✗ Network error — skipping'; ctx.after(1500, runNext); });
    }

    function pollJob(job) {
      fetch(job.statusUrl)
        .then(r => r.json())
        .then(s => {
          const done2  = s.done  || 0;
          const total2 = s.total || 0;
          if (s.running) {
            lbl.textContent = total2 > 0
              ? job.label + ': ' + done2 + ' / ' + total2 + '…'
              : job.label + ': fetching list…';
            ctx.after(450, () => pollJob(job));
          } else {
            lbl.textContent = job.label + ': done. ' + (s.message || '');
            ctx.after(600, runNext);
          }
        })
        .catch(() => setTimeout(() => pollJob(job), 1000));
    }

    runNext();
  }

  function selectOption(el, value) {
    document.querySelectorAll('.api-option').forEach(o => o.classList.remove('selected'));
    el.classList.add('selected');
    const radios = document.querySelectorAll('[name=api_choice]');
    radios.forEach(r => { r.checked = r.value === value; });
  }

  function testApi(url, resultId) {
    if (!url) return;
    const resultEl = document.getElementById(resultId || 'test-result');
    resultEl.textContent = 'Testing…';
    resultEl.style.color = 'var(--sp-muted)';
    fetch(`/ttrpg/reference/settings/test?url=${encodeURIComponent(url)}`)
      .then(r => r.json())
      .then(data => {
        if (data.ok) {
          resultEl.textContent = '✓ Connected — endpoints: ' + data.endpoints.join(', ') + '…';
          resultEl.style.color = 'var(--ttrpg-accent)';
        } else {
          resultEl.textContent = '✗ ' + data.error;
          resultEl.style.color = '#dc3545';
        }
      })
      .catch(() => {
        resultEl.textContent = '✗ Request failed';
        resultEl.style.color = '#dc3545';
      });
  }

  const NAMES = ["syncAll", "selectOption", "testApi"];
  exposeGlobals({ syncAll, selectOption, testApi });
  return () => {
    _dead = true;

    unexposeGlobals(NAMES);
  };
}
